import { Project } from '../../src'
import { fs, vol } from 'memfs'
import { Diagnostic, createConsoleLogger, GUID, type FileSystem, NowConfig } from '@servicenow/sdk-build-core'
import { createProject, FluentXmlFluentTest, XmlFluentXmlTest } from '../test-utils'

describe('Metadata directory', () => {
    describe('Building a project with metadata XMLs', () => {
        const scopeId = GUID()
        const warnings: string[] = []
        const project = new Project({
            packageJson: { name: 'test', version: '1.0.0' },
            config: { scope: 'x_test', scopeId },
            logger: { ...console, warn: (message) => warnings.push(message) },
        })

        const idA = project.registerExplicitId('test_table', 'a')
        const idB = project.registerExplicitId('test_table', 'b')
        const fluentFile = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['a'],
    table: 'test_table',
    data: {
        name: 'Test A',
    },
})

Record({
    $id: Now.ID['b'],
    table: 'test_table',
    data: {
        name: 'Test B',
    },
})
`,
        })

        const xmlFileWithMatchingName = project.addFile({
            path: `metadata/update/test_table_${idA}.xml`,
            content: `<?xml version="1.0"?>
<unload>
  <test_table action="INSERT_OR_UPDATE">
    <sys_id>${idA}</sys_id>
    <name>Override A</name>
  </test_table>
</unload>`,
        })

        const xmlFileWithDifferentName = project.addFile({
            path: `metadata/update/record.xml`, // Name is different from what will be generated by the record plugin
            content: `<?xml version="1.0"?>
<unload>
  <test_table action="INSERT_OR_UPDATE">
    <sys_id>${idB}</sys_id>
    <name>Override B</name>
  </test_table>
</unload>`,
        })

        const nonConflictingXmlFile = project.addFile({
            path: `metadata/unload/unique.xml`,
            content: `<?xml version="1.0"?>
<unload>
  <test_table action="INSERT_OR_UPDATE">
    <sys_id>12345</sys_id>
    <name>Unique</name>
  </test_table>
</unload>`,
        })

        test('No diagnostic errors', async () => {
            const diagnostics = [
                ...(await fluentFile.getDiagnostics()),
                ...(await xmlFileWithMatchingName.getDiagnostics()),
                ...(await xmlFileWithDifferentName.getDiagnostics()),
                ...(await nonConflictingXmlFile.getDiagnostics()),
            ]
            const errors = diagnostics.filter((d) => d.level === Diagnostic.Level.Error)
            expect(errors).toHaveLength(0)
        })

        test('Fluent files are handled normally', async () => {
            const fluentRecords = (await fluentFile.getRecords()).query()
            expect(fluentRecords).toHaveLength(2)
            expect(
                fluentRecords
                    .find((r) => r.getId().getValue() === idA)
                    ?.get('name')
                    .getValue()
            ).toBe('Test A')
            expect(
                fluentRecords
                    .find((r) => r.getId().getValue() === idB)
                    ?.get('name')
                    .getValue()
            ).toBe('Test B')
        })

        test('Metadata XML files are handled normally', async () => {
            const xmlRecordsA = (await xmlFileWithMatchingName.getRecords()).query()
            expect(xmlRecordsA).toHaveLength(1)
            expect(xmlRecordsA[0]?.getId().getValue()).toBe(idA)
            expect(xmlRecordsA[0]?.get('name').getValue()).toBe('Override A')

            const xmlRecordsB = (await xmlFileWithDifferentName.getRecords()).query()
            expect(xmlRecordsB).toHaveLength(1)
            expect(xmlRecordsB[0]?.getId().getValue()).toBe(idB)
            expect(xmlRecordsB[0]?.get('name').getValue()).toBe('Override B')

            const xmlRecordsC = (await nonConflictingXmlFile.getRecords()).query()
            expect(xmlRecordsC).toHaveLength(1)
            expect(xmlRecordsC[0]?.getId().getValue()).toBe('12345')
            expect(xmlRecordsC[0]?.get('name').getValue()).toBe('Unique')
        })

        test('Output has expected files', async () => {
            const output = await project.getOutput()
            expect(output.find((f) => f.path.includes('/sys_app'))).toBeDefined() // sys_app record
            expect(output.find((f) => f.path.includes('/sys_module'))).toBeDefined() // sys_module for package.json

            // The XML file with the same name should overwrite the Fluent output
            expect(output.find((f) => f.path.endsWith(`/dist/app/update/test_table_${idA}.xml`))).toMatchObject({
                content: xmlFileWithMatchingName.getContent(),
            })

            // The XML file with the different name should NOT overwrite the Fluent output
            expect(output.find((f) => f.path.endsWith(`/dist/app/update/record.xml`))).toMatchObject({
                content: xmlFileWithDifferentName.getContent(),
            })

            // The non-conflicting XML file should be present as well
            expect(output.find((f) => f.path.endsWith(`/dist/app/unload/unique.xml`))).toMatchObject({
                content: nonConflictingXmlFile.getContent(),
            })

            expect(output).toHaveLength(6)
        })
    })

    test('DEF0722127: Update package_json and version fields of sys_app xml during build if needed', async () => {
        vol.fromJSON({
            '/metadata/sys_app_11111111111111111111111111111111.xml': `<?xml version="1.0"?>
<record_update>
<sys_app action="INSERT_OR_UPDATE">
<sys_id>f05bf0947e1b41ce804297096207e266</sys_id>
<sys_scope display_value="sn_restapp">f05bf0947e1b41ce804297096207e266</sys_scope>
<active>true</active>
<can_edit_in_studio>true</can_edit_in_studio>
<enforce_license>log</enforce_license>
<guided_setup_guid/>
<hide_on_ui>false</hide_on_ui>
<installed_as_dependency>false</installed_as_dependency>
<js_level>es_latest</js_level>
<licensable>true</licensable>
<license_category>none</license_category>
<license_model>none</license_model>
<logo/>
<menu/>
<name>RestApp </name>
<private>false</private>
<restrict_table_access>false</restrict_table_access>
<runtime_access_tracking>permissive</runtime_access_tracking>
<scope>sn_restapp</scope>
<scoped_administration>false</scoped_administration>
<short_description/>
<source>sn_restapp</source>
<subscription_entitlement/>
<trackable>true</trackable>
<uninstall_blocked>false</uninstall_blocked>
<user_role/>
<version>0.0.1</version>
</sys_app>
</record_update>`,
            '/package.json': JSON.stringify({
                name: 'test',
                version: '0.0.2',
            }),
        })

        const project = new Project({
            fileSystem: fs as FileSystem,
            logger: createConsoleLogger(),
            rootDir: '/',
            config: NowConfig.parse(
                { scope: 'x_test', scopeId: '11111111111111111111111111111111' },
                createConsoleLogger()
            ),
        })

        const output = await project.getOutput()
        const sysApp = output.find((f) => f.path === '/dist/app/scope/sys_app_11111111111111111111111111111111.xml')
        expect(sysApp).toBeDefined()
        expect(sysApp?.content).toContain('<package_json>x_test/test/0.0.2/package.json</package_json>')
        expect(sysApp?.content).toContain('<version>0.0.2</version>')
    })

    test('Transforming a project with metadata XMLs', async () => {
        const project = new Project({
            packageJson: { name: 'test', version: '1.0.0' },
            config: { scope: 'x_test', scopeId: GUID() },
        })

        const idA = project.registerExplicitId('test_table', 'a')
        const idB = project.registerExplicitId('test_table', 'b')
        const fluentFile = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `import { Record } from '@servicenow/sdk/core'

// Exists in both Fluent code and metadata dir
Record({
    $id: Now.ID['a'],
    table: 'test_table',
    data: {
        name: 'Test A',
    },
})

// Exists only in Fluent code
Record({
    $id: Now.ID['b'],
    table: 'test_table',
    data: {
        name: 'Test B',
    },
})
`,
        })

        project.addFile({
            path: `metadata/update/test_table_${idA}.xml`,
            content: `<?xml version="1.0"?>
<unload>
  <test_table action="INSERT_OR_UPDATE">
    <sys_id>${idA}</sys_id>
    <name>Override A</name>
  </test_table>
</unload>`,
        })

        project.addFile({
            path: `metadata/update/unique.xml`,
            content: `<?xml version="1.0"?>
<unload>
  <test_table action="INSERT_OR_UPDATE">
    <sys_id>12345</sys_id>
    <name>Unique</name>
  </test_table>
</unload>`,
        })

        // This update should be ignored because the record exists in metadata dir
        const fluentAndMetadataUpdate = {
            path: 'fluent-and-metadata.xml',
            content: `<?xml version="1.0"?>
<unload>
  <test_table action="INSERT_OR_UPDATE" some_new_attr="123">
    <name>Updated A</name>
    <sys_id>${idA}</sys_id>
  </test_table>
</unload>`,
        }

        // This is the only update that should be handled
        const fluentOnlyUpdate = {
            path: 'fluent-only.xml',
            content: `<?xml version="1.0"?>
<record_update>
  <test_table action="INSERT_OR_UPDATE">
    <sys_id>${idB}</sys_id>
    <name>Updated B</name>
  </test_table>
</record_update>`,
        }

        // This update should be ignored because the record exists in metadata dir
        const metadataOnlyUpdate = {
            path: 'metadata-only.xml',
            content: `<?xml version="1.0"?>
<record_update>
  <test_table action="INSERT_OR_UPDATE">
    <!-- weird formatting and comments --> <sys_id>12345</sys_id>
    <name>Unique</name>
  </test_table>
</record_update>`,
        }

        const { changedFiles } = await project.transform([
            fluentAndMetadataUpdate,
            fluentOnlyUpdate,
            metadataOnlyUpdate,
        ])

        expect(changedFiles).toHaveLength(1)
        expect(changedFiles.find((f) => f.getPath().endsWith('src/fluent/index.now.ts'))).toBeDefined()

        expect(fluentFile.getContent()).toBe(`import { Record } from '@servicenow/sdk/core'

// Exists in both Fluent code and metadata dir
Record({
    $id: Now.ID['a'],
    table: 'test_table',
    data: {
        name: 'Test A',
    },
})

// Exists only in Fluent code
Record({
    $id: Now.ID['b'],
    table: 'test_table',
    data: {
        name: 'Updated B',
    },
})
`)
    })

    describe('Fluent => XML => Fluent', () => {
        test('generic record round-trips correctly', async () => {
            const project = createProject({ config: { scope: 'x_test' } })
            const roundTripTest = new FluentXmlFluentTest(project)

            const id = roundTripTest.addId('test_table', 'a')
            roundTripTest.addExpectedXmlFileNames(`test_table_${id}.xml`)

            roundTripTest.addFluentFragment(
                `
import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['a'],
    table: 'test_table',
    data: {
        name: 'Test A',
    },
})
`
            )

            await roundTripTest.verify()
        })
    })

    describe('XML => Fluent => XML', () => {
        test('ACL with roles round-trips correctly', async () => {
            const project = createProject({
                rootDir: __dirname,
                config: { scope: 'x_test' },
            })
            const originalFiles = [
                {
                    path: 'test_table_48c694e7c25a4a1481932a4517e31c73.xml',
                    content: `
<?xml version="1.0"?>
<record_update>
  <test_table action="INSERT_OR_UPDATE">
    <sys_id>48c694e7c25a4a1481932a4517e31c73</sys_id>
    <sys_scope display_value="x_test">11111111111111111111111111111111</sys_scope>
    <name>test</name>
  </test_table>
</record_update>
`,
                },
            ]
            const roundTripTest = new XmlFluentXmlTest(project, __dirname, originalFiles)
            await roundTripTest.verify()
        })
    })

    test('A sys_app in the metadata directory should override the Fluent-generated one', async () => {
        const project = new Project({ config: { scope: 'x_test', scopeId: '12345' } })
        const pkgId = project.registerExplicitId('sys_module', 'package_json')
        const bomId = project.registerExplicitId('sys_module', 'bom_json')

        const file = project.addFile({
            path: 'metadata/sys_app_12345.xml',
            content: `<?xml version="1.0" encoding="UTF-8"?>
<record_update table="sys_app">
    <sys_app action="INSERT_OR_UPDATE">
        <name>x_test</name>
        <version>1.0.0</version>
        <sys_id>12345</sys_id>
    </sys_app>
</record_update>`,
        })

        {
            const output = await project.getOutput()
            expect(output).toHaveLength(3)
            expect(output.map((o) => project.relativePath(o.path))).toEqual([
                `dist/app/update/sys_module_${bomId}.xml`,
                `dist/app/update/sys_module_${pkgId}.xml`,
                'dist/app/sys_app_12345.xml', // output sys_app is in the same relative location as the one from metadata dir (not in scope dir)
            ])
        }

        // Resolve the conflict by removing the sys_app definition and let Fluent generate it
        project.removeFile(file)

        {
            const output = await project.getOutput()
            expect(output).toHaveLength(3)
            expect(output.map((o) => project.relativePath(o.path))).toEqual([
                `dist/app/update/sys_module_${bomId}.xml`,
                `dist/app/update/sys_module_${pkgId}.xml`,
                'dist/app/scope/sys_app_12345.xml', // output sys_app is in the scope dir
            ])
        }
    })

    test('Metadata dir records should not produce warnings when they conflict with other metadata dir records', async () => {
        const warnings: string[] = []
        const project = new Project({ logger: { ...console, warn: (msg) => warnings.push(msg) } })
        const xml = `<?xml version="1.0" encoding="UTF-8"?>
<record_update table="sys_user_role">
    <sys_user_role action="INSERT_OR_UPDATE">
        <name>admin</name>
        <sys_id>11111</sys_id>
    </sys_user_role>
</record_update>`

        project.addFile({ path: 'metadata/update/record.xml', content: xml })
        project.addFile({ path: 'metadata/apply_once/record.xml', content: xml })

        await project.getOutput()
        expect(warnings).toHaveLength(0)
    })

    test('Module dependencies should not report conflicts for shared imports', async () => {
        const warnings: string[] = []
        const project = new Project({
            packageJson: {
                name: 'appname',
                version: '0.0.1',
                dependencies: {
                    dayjs: '1.11.13',
                    lodash: '4.17.23',
                },
            },
            logger: { ...console, warn: (msg) => warnings.push(msg) },
        })

        project.registerExplicitId('sys_module', 'dayjs@1.11.13/index.js', '3ff82227a4d74907b161e0df1200dcd5')
        project.registerExplicitId('sys_module', 'lodash@4.17.23/index.js', '46a818400c1e498aad94da81a43a5802')
        project.registerExplicitId('sys_module', 'lodash@4.17.23/has.js', 'edd3307d55284561a3c3a9e06f936067')

        const js1 = `import * as lodash from 'lodash'
        import has from 'lodash/has'
        import dayjs from 'dayjs'
        
        export const info = (message) => {
            lodash.toUpper(message)
            dayjs(message)
            has({}, '')
        }`
        const js2 = `import * as lodash from 'lodash'
        import has from 'lodash/has'
        import dayjs from 'dayjs'
        
        export const otherfunction = (message) => {  
            lodash.toUpper(message)
            dayjs(message)
            has({}, '')
        }`

        project.addFile({
            path: 'src/fluent/br.now.ts',
            content: `
            import { info } from '../server/script1.js'
            import { otherfunction } from '../server/script2.js'
            import { BusinessRule } from '@servicenow/sdk/core'

            BusinessRule({
                $id: '1',
                when: 'async',
                name: 'name',
                table: 'table',
                script: info
            })
            BusinessRule({
                $id: '2',
                when: 'async',
                name: 'name2',
                table: 'table',
                script: otherfunction
            })

            `,
        })

        project.addFile({ path: 'src/server/script1.js', content: js1 })
        project.addFile({ path: 'src/server/script2.js', content: js2 })

        await project.getOutput()
        expect(
            warnings.find((warning) =>
                warning.includes(
                    `Record "sys_module_3ff82227a4d74907b161e0df1200dcd5" is defined 2 times in the project`
                )
            )
        ).toBeFalsy()
        expect(
            warnings.find((warning) =>
                warning.includes(
                    `Record "sys_module_46a818400c1e498aad94da81a43a5802" is defined 2 times in the project`
                )
            )
        ).toBeFalsy()
        expect(
            warnings.find((warning) =>
                warning.includes(
                    `Record "sys_module_edd3307d55284561a3c3a9e06f936067" is defined 2 times in the project`
                )
            )
        ).toBeFalsy()
    })
})
